#include <bits/stdc++.h>
using namespace std;

class Solution {
    int islands(vector<vector<int>>& g) {
        int m = g.size(), n = g[0].size(), count = 0;
        vector<vector<bool>> seen(m, vector<bool>(n, false));
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        for (int i = 0; i < m; ++i) for (int j = 0; j < n; ++j) {
            if (g[i][j] != 1 || seen[i][j]) continue;
            ++count;
            queue<pair<int,int>> q; q.push({i,j}); seen[i][j] = true;
            while (!q.empty()) {
                auto p = q.front(); q.pop();
                for (int d = 0; d < 4; ++d) {
                    int x = p.first + dx[d], y = p.second + dy[d];
                    if (x < 0 || y < 0 || x >= m || y >= n ||
                        g[x][y] != 1 || seen[x][y]) continue;
                    seen[x][y] = true; q.push({x,y});
                }
            }
        }
        return count;
    }
public:
    int minDays(vector<vector<int>>& grid) {
        if (islands(grid) != 1) return 0;
        for (int i = 0; i < (int)grid.size(); ++i)
            for (int j = 0; j < (int)grid[0].size(); ++j) {
                if (grid[i][j] == 0) continue;
                grid[i][j] = 0;
                int count = islands(grid);
                grid[i][j] = 1;
                if (count != 1) return 1;
            }
        return 2;
    }
};
